import requests
from bs4 import BeautifulSoup

def detect_hate_speech(url):
    response = requests.get(url)
    soup = BeautifulSoup(response.text, 'html.parser')
    hs = soup.find_all('span', class_='hate-speech')
    for h in hs:
        if h.text.strip() == 'Hate Speech':
            return True
    return False

def report_hate_speech(url):
    if detect_hate_speech(url):
        print('Hate Speech detected on {}'.format(url))
    else:
        print('No Hate Speech detected on {}'.format(url))

def main():
    url = input('Enter the URL of the hate speech: ')
    report_hate_speech(url)

if __name__ == '__main__':
    main()
```

This bot will check if a given URL contains hate speech. If it does, it will report the URL to you.
